.brand-mark {
  width: 44px;
  height: 44px;
  flex: 0 0 auto;
  overflow: hidden;
  transition:
    width 0.35s cubic-bezier(0.2, 0.8, 0.2, 1),
    opacity 0.3s ease;
  transform-origin: center;
}
.brand-mark.is-away {
  width: 0;
  opacity: 0;
}
.brand-lockup:has(.brand-mark.is-away) {
  gap: 0;
}
.mascot-home-empty {
  display: block;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  border: 1px dashed rgba(229, 221, 210, 0.16);
  background: radial-gradient(circle at 50% 42%, rgba(229, 221, 210, 0.07), transparent 68%);
}
.mascot-roam {
  position: fixed;
  left: 0;
  top: 0;
  z-index: 4;
  width: 44px;
}
.add-button svg {
  display: block;
  flex: 0 0 auto;
}
.search-field {
  position: relative;
}
.field-mascot {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 0;
  margin-right: -12px;
  overflow: hidden;
  opacity: 0;
  color: var(--ink);
  transition:
    width 0.25s cubic-bezier(0.2, 0.8, 0.2, 1) 0.18s,
    margin-right 0.25s cubic-bezier(0.2, 0.8, 0.2, 1) 0.18s,
    opacity 0.2s ease 0.18s;
}
.search-field.is-mascot .field-mascot {
  width: 24px;
  margin-right: 0;
  opacity: 1;
  transition-delay: 0s, 0s, 0s;
}
.field-mascot svg {
  display: block;
  flex: 0 0 auto;
  transform: translateX(-6px) scale(0.7);
  opacity: 0;
  transition:
    transform 0.25s cubic-bezier(0.2, 0.8, 0.2, 1),
    opacity 0.2s ease;
}
.search-field.is-mascot .field-mascot svg {
  transform: translateY(1px);
  opacity: 1;
}
.field-mascot svg.is-typing {
  animation: mascot-bob 0.9s ease-in-out infinite;
}
@keyframes mascot-bob {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-1.5px);
  }
}
@media (prefers-reduced-motion: reduce) {
  .field-mascot svg.is-typing {
    animation: none;
  }
}
@property --wipe {
  syntax: "<percentage>";
  inherits: false;
  initial-value: 0%;
}
.search-field::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: #000000;
  -webkit-mask-image: linear-gradient(
    90deg,
    #000000 calc(var(--wipe) - 14%),
    transparent var(--wipe)
  );
  mask-image: linear-gradient(90deg, #000000 calc(var(--wipe) - 14%), transparent var(--wipe));
  transition: --wipe 0.38s cubic-bezier(0.2, 0.8, 0.2, 1) 0.18s;
}
.search-field.is-mascot::before {
  --wipe: 114%;
  transition-delay: 0s;
}
.search-field > * {
  position: relative;
  z-index: 1;
}
.capture-tool-button {
  height: 50px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 13px;
  border: 1px solid var(--library-border);
  border-radius: var(--button-radius-normal);
  background: #232320;
  color: var(--library-muted);
  cursor: pointer;
